export const SKILL_DESTINATION: ".claude/skills/trustabl-pre-coding/SKILL.md";

export interface ForgeOptions {
  /** SDK categories to add on top of the detected ones, e.g. ["mcp"]. The installed analyzer lists the accepted values. */
  policy?: string[];
  /** Languages to add: python, typescript, go. They filter each SDK's rules; they do not select an SDK. */
  lang?: string[];
  /** Write the skill to this path, relative to the repository (usually SKILL_DESTINATION). Must stay inside it; an existing file is replaced only if Forge generated it. */
  outputPath?: string;
}

export interface Stamp {
  date: string;
  rules: string;
  schema: number;
  sdks: string[];
  template: number;
}

export interface ForgeResult {
  /** The full SKILL.md content. */
  skill: string;
  /** SDK categories the skill covers. */
  sdks: string[];
  stamp: Stamp | null;
  /** Absolute path written, or null when outputPath was not given. */
  written: string | null;
  /** Anything the analyzer printed to stderr. */
  note: string;
}

/** Generate the pre-coding reliability skill for a repository directory. */
export function forge(target: string, options?: ForgeOptions): Promise<ForgeResult>;

/** The Forge stamp in a SKILL.md, or null when it was not generated by Forge. */
export function parseStamp(content: string): Stamp | null;

/** The analyzer's version, commit and build date. */
export function version(): Promise<string>;

/** Absolute path of the verified `trustabl` binary, downloading it on first use. */
export function ensureTrustabl(opts?: { env?: Record<string, string | undefined>; home?: string }): Promise<string>;
